* { box-sizing: border-box; }
:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #f5f3e9;
  background: #101927;
  font-size: 16px;
}
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 0%, #21364a 0, #101927 62%);
}
button { font: inherit; cursor: pointer; }
.board {
  width: min(100%, 740px);
  padding: clamp(24px, 5vw, 44px);
  border: 1px solid #344456;
  border-radius: 20px;
  background: #182533;
  box-shadow: 0 24px 70px #070d16a8;
}
.board-header { text-align: center; margin-bottom: 32px; }
.eyebrow, .team-label, .control-label, footer {
  margin: 0;
  color: #91a3b5;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .16em;
}
h1 { margin: 6px 0 4px; font-size: clamp(1.8rem, 6vw, 2.5rem); line-height: 1.1; }
.subtitle { margin: 0; color: #aab8c5; }
.score-grid { display: grid; grid-template-columns: 1fr 32px 1fr; align-items: center; gap: 12px; }
.team {
  min-width: 0;
  padding: 22px 16px 18px;
  border: 1px solid #344456;
  border-radius: 14px;
  text-align: center;
  background: #1e2c3a;
}
.team-coral { --accent: #ff786b; --accent-dark: #562f35; }
.team-mint { --accent: #65dfb0; --accent-dark: #24483f; }
.team-label { color: var(--accent); }
.team h2 { margin: 7px 0 2px; font-size: 1.2rem; }
.score {
  display: block;
  overflow: hidden;
  color: var(--accent);
  font-size: clamp(4rem, 13vw, 6.5rem);
  font-variant-numeric: tabular-nums;
  font-weight: 900;
  line-height: 1.2;
}
.score-buttons { display: flex; gap: 8px; margin-top: 12px; }
.score-buttons button, .step-button, .undo-button, .reset-button {
  min-height: 48px;
  border: 1px solid #405264;
  border-radius: 9px;
  color: #f5f3e9;
  background: #293a49;
  font-weight: 800;
  transition: transform .12s ease, background-color .12s ease, border-color .12s ease;
}
.score-buttons button { flex: 1; padding: 8px 4px; color: var(--accent); background: var(--accent-dark); border-color: color-mix(in srgb, var(--accent) 40%, #344456); }
button:hover:not(:disabled) { transform: translateY(-2px); border-color: #91a3b5; }
.score-buttons button:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-dark) 70%, var(--accent)); }
button:active:not(:disabled) { transform: translateY(1px) scale(.98); }
button:focus-visible { outline: 3px solid #f5f3e9; outline-offset: 3px; }
button:disabled { cursor: not-allowed; opacity: .45; }
.divider { color: #91a3b5; font-size: .8rem; font-weight: 900; text-align: center; }
.game-controls { display: flex; justify-content: space-between; align-items: end; gap: 18px; margin-top: 26px; padding-top: 22px; border-top: 1px solid #344456; }
.period-control { display: grid; gap: 8px; }
.period-stepper { display: flex; align-items: center; gap: 12px; }
.period-stepper output { min-width: 24px; text-align: center; font-size: 1.4rem; font-weight: 900; font-variant-numeric: tabular-nums; }
.step-button { width: 44px; min-height: 44px; font-size: 1.3rem; }
.action-buttons { display: flex; gap: 9px; }
.undo-button, .reset-button { padding: 10px 15px; }
.reset-button { border-color: #ff786b; color: #ffb0a7; background: #382a32; }
.reset-button:hover:not(:disabled) { background: #56343a; }
footer { margin-top: 25px; text-align: center; font-size: .7rem; }
@media (max-width: 520px) {
  .board { padding: 25px 18px; }
  .score-grid { grid-template-columns: 1fr 20px 1fr; gap: 7px; }
  .team { padding: 18px 9px 14px; }
  .score-buttons { gap: 5px; }
  .score-buttons button { min-height: 46px; padding-inline: 2px; }
  .game-controls { align-items: stretch; flex-direction: column; }
  .period-control { display: flex; justify-content: space-between; align-items: center; }
  .action-buttons > button { flex: 1; }
}

const scores = { a: 0, b: 0 };
let period = 1;
let lastScoreChange = null;

const scoreOutputs = {
  a: document.querySelector('#score-a'),
  b: document.querySelector('#score-b')
};
const periodOutput = document.querySelector('#period');
const undoButton = document.querySelector('#undo');

function render() {
  scoreOutputs.a.value = scores.a;
  scoreOutputs.a.textContent = scores.a;
  scoreOutputs.b.value = scores.b;
  scoreOutputs.b.textContent = scores.b;
  periodOutput.value = period;
  periodOutput.textContent = period;
  undoButton.disabled = lastScoreChange === null;
  document.querySelector('#period-down').disabled = period === 1;
  document.querySelector('#period-up').disabled = period === 4;
}

document.querySelectorAll('[data-team][data-points]').forEach((button) => {
  button.addEventListener('click', () => {
    const team = button.dataset.team;
    const points = Number(button.dataset.points);
    lastScoreChange = { team, points };
    scores[team] += points;
    render();
  });
});

undoButton.addEventListener('click', () => {
  if (!lastScoreChange) return;
  scores[lastScoreChange.team] -= lastScoreChange.points;
  lastScoreChange = null;
  render();
});

document.querySelector('#period-down').addEventListener('click', () => {
  if (period > 1) period -= 1;
  render();
});

document.querySelector('#period-up').addEventListener('click', () => {
  if (period < 4) period += 1;
  render();
});

document.querySelector('#reset').addEventListener('click', () => {
  scores.a = 0;
  scores.b = 0;
  period = 1;
  lastScoreChange = null;
  render();
});

render();
